create table if not exists public.players(id uuid primary key default gen_random_uuid(),name text not null,room_code text not null,level int not null default 1,xp int not null default 0,score int not null default 0,avatar text,weapon text,hp int not null default 100,created_at timestamptz default now(),updated_at timestamptz default now());create index if not exists players_room_idx on public.players(room_code);alter table public.players enable row level security;create policy "players readable" on public.players for select using (true);create policy "players insertable" on public.players for insert with check (true);create policy "players updatable" on public.players for update using (true);